        "code": {
          "text": "Distress when away from partner or home"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Marked distress most days; patient reports feeling physically sick and being unable to focus when her partner is away for the day."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-2",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-2",
        "status": "final",
        "code": {
          "text": "Anticipatory anxiety"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Anxiety the night before her partner goes to work or social activities; symptoms have worsened with his office days."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-3",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-3",
        "status": "final",
        "code": {
          "text": "Worry and checking related to partner's safety"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Repetitive checking of her partner's location and messages, with worry that something bad will happen and he will not come home."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-4",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-4",
        "status": "final",
        "code": {
          "text": "Avoidance and difficulty being alone"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Avoids being alone outside home; may cancel or delay appointments if her partner cannot accompany her and uses grocery delivery. Avoids public transport and busy indoor spaces alone. Can walk a short distance around the block with her partner."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-5",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-5",
        "status": "final",
        "code": {
          "text": "Sleep disturbance and nightmares"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Difficulty sleeping when her partner is not in the flat; waits awake until he returns. Occasional nightmares about him going missing or having an accident."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-6",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-6",
        "status": "final",
        "code": {
          "text": "Somatic symptoms associated with partner leaving"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Abdominal tightness, nausea, and mild headache when her partner is about to leave; symptoms settle when he is home."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-7",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-7",
        "status": "final",
        "code": {
          "text": "Caffeine use"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Approximately 3–4 coffees per day, more on stress days; reports that increased coffee on her partner's office mornings makes anxiety worse."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-8",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-8",
        "status": "final",
        "code": {
          "text": "Alcohol use"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Rare alcohol use: 1–2 drinks per month."
      }
    },
