        "resourceType": "Observation",
        "id": "observation-9",
        "status": "final",
        "code": {
          "text": "Illicit substance use"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Reports no illicit substance use."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-10",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-10",
        "status": "final",
        "code": {
          "text": "Tobacco use"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Non-smoker."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-11",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-11",
        "status": "final",
        "code": {
          "text": "Mood and depressive symptoms"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No clear current major depressive episode. Denies persistent low mood, hopelessness, and anhedonia; still enjoys drawing, shows, and online gaming."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-12",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-12",
        "status": "final",
        "code": {
          "text": "Suicidal ideation and self-harm thoughts"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Denies suicidal ideation and self-harm thoughts."
      }
    },
    {
