      "resource": {
        "resourceType": "Observation",
        "id": "observation-13",
        "status": "final",
        "code": {
          "text": "Homicidal ideation"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No homicidal ideation reported."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-14",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-14",
        "status": "final",
        "code": {
          "text": "Mental status examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Neat with good hygiene, cooperative, and good eye contact via camera. Calm but clearly anxious; mood described as “anxious,” affect congruent and reactive. Speech normal; thought form linear, with content dominated by worries about partner safety and being alone. Cognition grossly intact; good insight."
      }
    },
